<?php use function KB\{e,url}; use KB\Security; ?>
<section class="page-heading"><div><span class="eyebrow">THE QUESTION BANK</span><h1>Make room for discovery.</h1><p>Create thoughtful questions. Every edit applies to new attempts, never to answers already in progress.</p></div><a class="button" href="<?= e(url('admin/questions',['new'=>1])) ?>">Add question +</a></section>
<?php if($error): ?><div class="notice error"><?= e($error) ?></div><?php endif; ?>
<section class="panel" id="question-editor"><div class="section-heading"><h2><?= $edit?'Edit question #'.(int)$edit['id']:'Add a new question' ?></h2><span class="badge">4 answer options</span></div><form method="post" class="stack"><?= Security::csrfField() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-grid"><label>Category<input name="category" maxlength="80" required list="categories" value="<?= e($edit['category']??'Matthew') ?>"><datalist id="categories"><option>Matthew</option><option>Mark</option><option>Luke</option><option>John</option><option>Old Testament</option></datalist></label><label>Availability<select name="is_active"><option value="1">Active — available for quizzes</option><option value="0" <?= isset($edit)&&!(int)$edit['is_active']?'selected':'' ?>>Draft — hidden from quizzes</option></select></label></div><label>Question<textarea name="question_text" rows="3" minlength="8" maxlength="5000" required><?= e($edit['question_text']??'') ?></textarea></label><div class="form-grid"><?php foreach(['a','b','c','d'] as $i=>$letter): ?><label>Option <?= strtoupper($letter) ?><input name="option_<?= $letter ?>" maxlength="1000" required value="<?= e($edit['option_'.$letter]??'') ?>"></label><?php endforeach; ?></div><div class="form-grid"><label>Correct answer<select name="correct_option"><?php foreach(['A','B','C','D'] as $i=>$letter): ?><option value="<?= $i ?>" <?= (int)($edit['correct_option']??0)===$i?'selected':'' ?>>Option <?= $letter ?></option><?php endforeach; ?></select></label><label>Scripture reference<input name="reference" maxlength="160" placeholder="e.g. Matthew 5:3" value="<?= e($edit['reference']??'') ?>"></label></div><label>Explanation <span class="muted">(optional; used for practice and results)</span><textarea name="explanation" rows="2" maxlength="5000"><?= e($edit['explanation']??'') ?></textarea></label><div class="form-actions"><button class="button"><?= $edit?'Save changes':'Add to question bank' ?></button><a class="button secondary" href="<?= e(url('admin/questions')) ?>">Clear form</a></div></form></section>
<section class="panel"><div class="section-heading"><h2>Your questions</h2><form class="search-form" method="get"><input type="hidden" name="route" value="admin/questions"><input name="q" type="search" aria-label="Search questions" placeholder="Search questions or categories…" value="<?= e($search) ?>"><button class="button secondary small">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Question</th><th>Category</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($questions as $q): ?><tr><td><strong><?= e($q['question_text']) ?></strong><small><?= e($q['reference']) ?> · #<?= (int)$q['id'] ?></small></td><td><?= e($q['category']) ?></td><td><span class="badge <?= $q['is_active']?'green':'neutral' ?>"><?= $q['is_active']?'Active':'Draft' ?></span></td><td class="actions"><a href="<?= e(url('admin/questions',['edit'=>$q['id']])) ?>">Edit</a><form method="post" data-confirm="Delete this question? Existing attempts will be preserved."><?= Security::csrfField() ?><input type="hidden" name="id" value="<?= (int)$q['id'] ?>"><input type="hidden" name="action" value="delete"><button class="danger-link">Delete</button></form></td></tr><?php endforeach; ?></tbody></table><?php if(!$questions): ?><p class="empty">No questions match this search.</p><?php endif; ?></div><?php require __DIR__.'/../pagination.php'; ?></section>
